insert into recipes_sweettreats (user_id, name, ingredients, steps, category, image_url, is_public, created_at) values
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Classic Fudgy Brownies', ARRAY['200g dark chocolate, chopped', '150g butter', '200g caster sugar', '3 large eggs', '75g plain flour', '30g cocoa powder', '1/2 tsp vanilla extract', 'Pinch of salt', '100g chocolate chips (optional)'], '1. Preheat oven to 180°C. Line a 20cm square tin with parchment paper.
2. Melt chocolate and butter in a double boiler until smooth.
3. Remove from heat and whisk in sugar until combined.
4. Beat in eggs one at a time, then add vanilla.
5. Sift flour and cocoa powder, fold into mixture with salt.
6. Add chocolate chips if using.
7. Pour into prepared tin and bake for 25-30 min.
8. Cool completely before cutting into squares.', 'chocolate', 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=400', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Decadent Chocolate Cake', ARRAY['200g plain flour', '200g caster sugar', '75g cocoa powder', '2 tsp baking powder', '1 tsp baking soda', '2 eggs', '250ml buttermilk', '125ml vegetable oil', '2 tsp vanilla extract', '250ml hot coffee'], '1. Preheat oven to 180°C. Grease two 20cm cake tins.
2. Mix all dry ingredients in a large bowl.
3. Whisk eggs, buttermilk, oil, and vanilla in another bowl.
4. Combine wet and dry ingredients.
5. Gradually add hot coffee, mixing until smooth.
6. Divide between tins and bake for 30-35 min.
7. Cool completely before frosting.
8. Frost with your favorite chocolate buttercream.', 'chocolate', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=400', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Cake Pops', ARRAY['1 box chocolate cake mix (plus ingredients called for)', '450g cream cheese frosting', '700g chocolate candy coating', '48 cake pop sticks', 'Sprinkles for decoration'], '1. Bake cake according to package directions. Cool completely.
2. Crumble cake into fine crumbs.
3. Mix crumbs with frosting until well combined.
4. Roll mixture into 48 balls, place on baking sheet.
5. Chill for 2 h.
6. Melt chocolate coating according to package directions.
7. Dip stick 1cm into chocolate, then insert into cake ball.
8. Dip entire cake pop into chocolate, tap off excess.
9. Add sprinkles before chocolate sets. Place in styrofoam to dry.', 'chocolate', 'https://plus.unsplash.com/premium_photo-1667031518595-9cb4b0d504ef?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8NXx8Y2hvY29sYXRlJTIwYmFya3xlbnwwfHwwfHx8MA%3D%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Silky Chocolate Mousse', ARRAY['200g dark chocolate (70%), chopped', '6 large eggs, separated', '75g caster sugar', '300ml double cream', '2 tbsp coffee liqueur (optional)', 'Pinch of salt'], '1. Melt chocolate in double boiler until smooth. Cool slightly.
2. Whisk egg yolks with half the sugar until pale.
3. Stir melted chocolate and liqueur into yolk mixture.
4. Whip cream to soft peaks.
5. Beat egg whites with salt until foamy, gradually add remaining sugar.
6. Beat until stiff peaks form.
7. Fold 1/3 of whites into chocolate mixture.
8. Fold in whipped cream, then remaining whites.
9. Spoon into glasses, chill for 4 h before serving.', 'chocolate', 'https://bakewithzoha.com/wp-content/uploads/2024/10/chocolate-mousse-featured.jpg', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Lava Cakes', ARRAY['100g dark chocolate, chopped', '100g butter', '2 large eggs', '2 large egg yolks', '60g caster sugar', '2 tbsp plain flour', 'Butter for ramekins', 'Cocoa powder for dusting'], '1. Preheat oven to 220°C. Butter 4 ramekins and dust with cocoa.
2. Melt chocolate and butter in double boiler.
3. Whisk eggs, egg yolks, and sugar until thick and pale.
4. Stir in melted chocolate mixture and flour.
5. Divide between ramekins.
6. Bake for 12-14 min until edges are firm but center jiggles.
7. Let stand 1 minute, then run knife around edges.
8. Invert onto plates and serve immediately with ice cream.', 'chocolate', 'https://images.unsplash.com/photo-1606890737304-57a1ca8a5b62?w=400', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Truffles', ARRAY['400g dark chocolate, finely chopped', '300ml double cream', '2 tbsp butter', '2 tbsp brandy or rum (optional)', 'Cocoa powder for rolling', 'Chopped nuts (optional)', 'Shredded coconut (optional)'], '1. Place chocolate in a large bowl.
2. Heat cream in a saucepan until just simmering.
3. Pour hot cream over chocolate, let sit 2 min.
4. Stir from center outward until smooth.
5. Stir in butter and alcohol if using.
6. Cover and chill for 2 h until firm.
7. Using a spoon, scoop mixture and roll into balls.
8. Roll in cocoa powder, nuts, or coconut.
9. Store in refrigerator for up to 1 week.', 'chocolate', 'https://whatjessicabakednext.com/wp-content/uploads/2023/01/Choc-Truffles-WJBN.jpg', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Chip Cookies', ARRAY['225g plain flour', '1 tsp baking soda', '1 tsp salt', '225g butter, softened', '150g brown sugar', '100g caster sugar', '2 large eggs', '2 tsp vanilla extract', '350g chocolate chips'], '1. Preheat oven to 190°C.
2. Mix flour, baking soda, and salt in a bowl.
3. Cream butter and both sugars until light and fluffy.
4. Beat in eggs one at a time, then vanilla.
5. Gradually mix in flour mixture.
6. Stir in chocolate chips.
7. Drop rounded tablespoons onto ungreased baking sheets.
8. Bake 9-11 min until golden brown.
9. Cool on baking sheet for 2 min before removing.', 'chocolate', 'https://images.unsplash.com/photo-1499636136210-6f4ee915583e?w=400', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Fudge', ARRAY['400g dark chocolate, chopped', '397g sweetened condensed milk', '50g butter', '1 tsp vanilla extract', '100g chopped walnuts (optional)', 'Pinch of salt'], '1. Line a 20cm square tin with parchment paper.
2. Melt chocolate, condensed milk, and butter in double boiler.
3. Stir constantly until smooth and thick (about 10 min).
4. Remove from heat, stir in vanilla, salt, and nuts if using.
5. Pour into prepared tin and smooth top.
6. Refrigerate for 2 h until set.
7. Cut into squares and serve.
8. Store covered in refrigerator for up to 1 week.', 'chocolate', 'https://media.istockphoto.com/id/1185416324/photo/homemade-raw-milk-free-sugar-free-vegan-chocolate-brownies-or-fudge.webp?a=1&b=1&s=612x612&w=0&k=20&c=aWzJkgAAXtoWvaJdrzf_X5LsLMkpZhCY5iK9AJ6IbXM=', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Cupcakes', ARRAY['175g plain flour', '175g caster sugar', '40g cocoa powder', '1.5 tsp baking powder', '1/2 tsp salt', '2 eggs', '175ml milk', '85ml vegetable oil', '1 tsp vanilla extract', '175ml hot water'], '1. Preheat oven to 180°C. Line muffin tin with paper cases.
2. Mix flour, sugar, cocoa, baking powder, and salt.
3. Beat eggs, milk, oil, and vanilla in another bowl.
4. Combine wet and dry ingredients.
5. Gradually stir in hot water until smooth.
6. Fill cases 2/3 full.
7. Bake 18-20 min until toothpick comes out clean.
8. Cool completely before frosting with chocolate buttercream.', 'chocolate', 'https://www.lifeloveandsugar.com/wp-content/uploads/2023/06/Chocolate-Cupcakes-Recipe3.jpg', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Chocolate Bark', ARRAY['500g dark chocolate, chopped', '100g dried cranberries', '100g chopped almonds', '50g pistachios, chopped', '2 tbsp sea salt flakes', '50g white chocolate, melted (for drizzling)'], '1. Line a large baking sheet with parchment paper.
2. Melt dark chocolate in double boiler until smooth.
3. Pour onto prepared baking sheet, spread to 1cm thickness.
4. Sprinkle cranberries, almonds, and pistachios over chocolate.
5. Gently press toppings into chocolate.
6. Drizzle with melted white chocolate.
7. Sprinkle with sea salt.
8. Refrigerate for 1 h until set.
9. Break into pieces and store in airtight container.', 'chocolate', 'https://images.unsplash.com/photo-1679143121492-820c69266ab8?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MTB8fGNob2NvbGF0ZSUyMGJhcmt8ZW58MHx8MHx8fDA%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Chocolate Chip Cookies', ARRAY['2 1/4 cups plain flour', '1 tsp baking soda', '1 tsp salt', '1 cup vegan butter, softened', '3/4 cup brown sugar', '3/4 cup granulated sugar', '1/4 cup non-dairy milk', '2 tsp vanilla extract', '2 cups vegan chocolate chips'], '1. Preheat oven to 190°C. Line baking sheets with parchment.
2. Mix flour, baking soda, and salt in a bowl.
3. Cream vegan butter and both sugars until fluffy.
4. Beat in non-dairy milk and vanilla extract.
5. Gradually mix in flour mixture until just combined.
6. Fold in vegan chocolate chips.
7. Drop rounded tablespoons onto prepared baking sheets.
8. Bake 9-11 min until edges are golden brown.
9. Cool on baking sheet for 5 min.
10. Transfer to wire rack to cool completely.', 'vegan', 'https://images.unsplash.com/photo-1657418830273-40c19cfff4d7?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8M3x8Y2hvY29sYXRlJTIwY2hpcCUyMGNvb2tpZXN8ZW58MHx8MHx8fDA%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Brownies', ARRAY['1 cup plain flour', '1 cup cocoa powder', '1 1/2 cups granulated sugar', '1 tsp baking powder', '1/2 tsp salt', '1/2 cup coconut oil, melted', '1/2 cup non-dairy milk', '1 tsp vanilla extract', '1/2 cup vegan chocolate chips', '1/2 cup chopped walnuts (optional)'], '1. Preheat oven to 180°C. Line 20cm square pan with parchment.
2. Mix flour, cocoa powder, sugar, baking powder, and salt.
3. In another bowl, whisk melted coconut oil, non-dairy milk, and vanilla.
4. Pour wet ingredients into dry ingredients, mix until just combined.
5. Fold in chocolate chips and walnuts if using.
6. Pour batter into prepared pan and smooth top.
7. Bake 25-30 min until toothpick has few moist crumbs.
8. Cool completely in pan before cutting.
9. Cut into squares and serve.', 'vegan', 'https://images.unsplash.com/photo-1612078960206-1709f1f0c969?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MTZ8fGJyb3duaWVzfGVufDB8fDB8fHww', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Banana Bread', ARRAY['3 large ripe bananas, mashed', '1/3 cup melted coconut oil', '3/4 cup brown sugar', '1/4 cup non-dairy milk', '1 tsp vanilla extract', '1 3/4 cups plain flour', '1 tsp baking soda', '1/2 tsp salt', '1/2 tsp cinnamon', '1/2 cup chopped walnuts (optional)'], '1. Preheat oven to 180°C. Grease 23x13cm loaf pan.
2. Mash bananas in large bowl until smooth.
3. Mix in melted coconut oil, brown sugar, non-dairy milk, and vanilla.
4. In separate bowl, whisk flour, baking soda, salt, and cinnamon.
5. Add dry ingredients to wet ingredients, mix until just combined.
6. Fold in walnuts if using.
7. Pour batter into prepared loaf pan.
8. Bake 60-65 min until toothpick comes out clean.
9. Cool in pan for 10 min, then turn out onto wire rack.', 'vegan', 'https://images.unsplash.com/photo-1632931057819-4eefffa8e007?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8YmFuYW5hJTIwYnJlYWR8ZW58MHx8MHx8fDA%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Chocolate Cake', ARRAY['1 1/2 cups plain flour', '1 cup granulated sugar', '1/4 cup cocoa powder', '1 tsp baking soda', '1/2 tsp salt', '1 cup water', '1/3 cup vegetable oil', '1 tbsp white vinegar', '1 tsp vanilla extract', 'Vegan chocolate frosting'], '1. Preheat oven to 180°C. Grease 23cm round cake pan.
2. Mix flour, sugar, cocoa powder, baking soda, and salt.
3. In another bowl, whisk water, oil, vinegar, and vanilla.
4. Pour wet ingredients into dry ingredients, mix until smooth.
5. Pour batter into prepared pan.
6. Bake 30-35 min until toothpick comes out clean.
7. Cool in pan for 10 min.
8. Turn out onto wire rack to cool completely.
9. Frost with vegan chocolate frosting when cool.', 'vegan', 'https://plus.unsplash.com/premium_photo-1715015439764-1e8d37d5c6c9?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8OXx8Y2hvY29sYXRlJTIwY2FrZXxlbnwwfHwwfHx8MA%3D%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Coconut Macaroons', ARRAY['3 cups unsweetened shredded coconut', '2/3 cup coconut cream (thick part of canned coconut milk)', '1/2 cup maple syrup', '1 tsp vanilla extract', '1/4 tsp salt', '2 tbsp coconut flour', '100g vegan dark chocolate, melted (optional)'], '1. Preheat oven to 160°C. Line baking sheet with parchment.
2. Mix shredded coconut, coconut cream, maple syrup, vanilla, and salt.
3. Stir in coconut flour until mixture holds together.
4. Let mixture sit for 10 min to thicken.
5. Using hands or ice cream scoop, form into mounds.
6. Place on prepared baking sheet.
7. Bake 18-22 min until golden brown.
8. Cool completely on baking sheet.
9. Dip bottoms in melted chocolate if desired, let set.', 'vegan', 'https://media.istockphoto.com/id/2173370660/photo/pink-macarons.webp?a=1&b=1&s=612x612&w=0&k=20&c=Gj6NxnulO2l81lRs9NbBPgsXmQzxA4f8FtRmBNme4_I=', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Lemon Bars', ARRAY['Crust: 1 1/2 cups plain flour', '1/2 cup powdered sugar', '1/4 tsp salt', '1/2 cup vegan butter, cold', 'Filling: 1 can (400ml) coconut milk', '3/4 cup granulated sugar', '1/3 cup fresh lemon juice', '2 tbsp lemon zest', '3 tbsp cornstarch', 'Powdered sugar for dusting'], '1. Preheat oven to 160°C. Line 20cm square pan with parchment.
2. Mix flour, powdered sugar, and salt for crust.
3. Cut in cold vegan butter until mixture resembles coarse crumbs.
4. Press into prepared pan, bake 18-20 min until lightly golden.
5. Whisk coconut milk, sugar, lemon juice, zest, and cornstarch.
6. Pour over hot crust.
7. Bake 25-30 min until filling is set.
8. Cool completely before dusting with powdered sugar.
9. Cut into bars and serve.', 'vegan', 'https://images.unsplash.com/photo-1528252941458-c1d19f902318?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8bGVtb24lMjBiYXJzfGVufDB8fDB8fHww', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Oatmeal Cookies', ARRAY['1 cup plain flour', '1 cup old-fashioned oats', '1/2 cup brown sugar', '1/2 cup granulated sugar', '1/2 tsp baking soda', '1/2 tsp cinnamon', '1/4 tsp salt', '1/2 cup coconut oil, melted', '1/4 cup non-dairy milk', '1 tsp vanilla extract', '1/2 cup raisins or vegan chocolate chips'], '1. Preheat oven to 180°C. Line baking sheets with parchment.
2. Mix flour, oats, both sugars, baking soda, cinnamon, and salt.
3. In another bowl, whisk melted coconut oil, non-dairy milk, and vanilla.
4. Pour wet ingredients into dry ingredients, mix until combined.
5. Stir in raisins or chocolate chips.
6. Drop rounded tablespoons onto prepared baking sheets.
7. Bake 12-15 min until edges are golden.
8. Cool on baking sheet for 5 min.
9. Transfer to wire rack to cool completely.', 'vegan', 'https://images.unsplash.com/photo-1631311253861-52eaf0337adb?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8b2F0bWVhbCUyMGNvb2tpZXN8ZW58MHx8MHx8fDA%3D', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'White Chocolate Mousse', ARRAY['1 package (340g) silken tofu', '200g vegan dark chocolate, melted', '1/4 cup maple syrup', '2 tbsp coconut cream', '1 tsp vanilla extract', 'Pinch of salt', 'Fresh berries for garnish', 'Mint leaves for garnish'], '1. Drain silken tofu and pat dry with paper towels.
2. Melt chocolate in double boiler or microwave, let cool slightly.
3. Blend tofu in food processor until completely smooth.
4. Add melted chocolate, maple syrup, coconut cream, vanilla, and salt.
5. Blend until smooth and creamy, scraping sides as needed.
6. Taste and adjust sweetness if needed.
7. Divide among serving glasses.
8. Chill for at least 2 h until set.
9. Garnish with berries and mint before serving.', 'vegan', 'https://plus.unsplash.com/premium_photo-1713459199001-03abf7c82730?w=500&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8OXx8bW91c3NlfGVufDB8fDB8fHww', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Energy Balls', ARRAY['1 cup pitted dates, soaked in warm water for 10 min', '1 cup raw almonds', '1/4 cup chia seeds', '1/4 cup unsweetened cocoa powder', '2 tbsp almond butter', '1 tsp vanilla extract', 'Pinch of salt', 'Shredded coconut for rolling (optional)'], '1. Drain soaked dates and remove any remaining pits.
2. Process almonds in food processor until finely chopped.
3. Add dates, chia seeds, cocoa powder, almond butter, vanilla, and salt.
4. Process until mixture forms a sticky paste.
5. If too dry, add 1-2 tbsp water.
6. Roll mixture into walnut-sized balls.
7. Roll in shredded coconut if desired.
8. Place on baking sheet and refrigerate 30 min to firm up.
9. Store in refrigerator for up to 1 week.', 'vegan', 'https://media.istockphoto.com/id/612408302/photo/vegan-sweet-balls-food-on-table.webp?a=1&b=1&s=612x612&w=0&k=20&c=AXyxBrxAcPASP8TNHCyfTMct2O-6dmkeL1898ZQt5_I=', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Vegan Apple Crisp', ARRAY['Filling: 6 large apples, peeled and sliced', '1/2 cup granulated sugar', '2 tbsp plain flour', '1 tsp cinnamon', '1/4 tsp nutmeg', 'Topping: 1 cup old-fashioned oats', '3/4 cup plain flour', '3/4 cup brown sugar', '1/2 cup vegan butter, cold', '1/2 tsp cinnamon', '1/4 tsp salt'], '1. Preheat oven to 190°C. Grease 23x33cm baking dish.
2. Toss sliced apples with sugar, flour, cinnamon, and nutmeg.
3. Place apple mixture in prepared baking dish.
4. Mix oats, flour, brown sugar, cinnamon, and salt for topping.
5. Cut in cold vegan butter until mixture resembles coarse crumbs.
6. Sprinkle topping evenly over apples.
7. Bake 35-40 min until topping is golden and apples are tender.
8. Cool for 10 min before serving.
9. Serve warm with vegan ice cream if desired.', 'vegan', 'https://media.istockphoto.com/id/900302364/photo/detail-of-spoonful-of-apple-crisp-or-apple-crumble-baked-dessert.webp?a=1&b=1&s=612x612&w=0&k=20&c=MbkiHsB95ZA32VN1PpqA6Y_65VXyv1yMzVfr5gqD2vY=', true, now()),
  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Classic Sugar Cookies', ARRAY['2 3/4 cups plain flour', '1 tsp baking soda', '1/2 tsp salt', '1 cup butter, softened', '1 1/2 cups granulated sugar', '1 large egg', '1 tsp vanilla extract', 'Colored sugar for rolling'], '1. Preheat oven to 190°C.
