  ('652e1838-be79-42ee-96e4-9cabfd7a6e40', 'Peanut Butter Cookies', ARRAY['1 1/4 cups plain flour', '3/4 tsp baking soda', '1/2 tsp salt', '1/2 cup butter, softened', '1/2 cup peanut butter', '1/2 cup granulated sugar', '1/2 cup brown sugar', '1 large egg', '1 tsp vanilla extract'], '1. Preheat oven to 190°C.
